// Segundo control de la regla de contencion financiera.
// El System Prompt le ordena al agente no superar 200 caracteres, pero una
// instruccion en lenguaje natural es una recomendacion, no una garantia: si el
// modelo se excede, el costo lo paga la API de sintesis de voz. Este nodo corta
// por codigo, en el ultimo limite de oracion antes de los 200 caracteres, para
// no entregar una frase partida al medio.
const LIMITE = 200;
const crudo = ($input.first().json.output ?? '').toString().trim();

let texto = crudo;
let truncado = false;

if (crudo.length > LIMITE) {
  const corte = crudo.slice(0, LIMITE);
  const fin = Math.max(corte.lastIndexOf('. '), corte.lastIndexOf('? '),
                       corte.lastIndexOf('! '));
  texto = fin > 60 ? corte.slice(0, fin + 1) : corte.trim() + '.';
  truncado = true;
}

return [{ json: {
  texto_para_voz:   texto,
  caracteres:       texto.length,
  caracteres_crudo: crudo.length,
  truncado_por_codigo: truncado,
  chat_id: $('Contrato de Voz').first().json.chat_id
}}];

// PROTOCOLO DE PRIVACIDAD TRANSACCIONAL
// La voz de una persona es un dato biometrico. Este nodo cierra el circuito
// descartando de forma explicita todo payload binario del item que continua,
// de modo que ni el audio entrante del cliente ni el audio sintetizado queden
// adheridos al resultado de la ejecucion.
//
// Este control es complementario, no principal. El control principal es la
// configuracion del workflow: no se persisten datos de ejecuciones exitosas ni
// fallidas, de modo que los binarios viven solo en la memoria volatil del
// proceso durante la ejecucion y se liberan al terminar.
const item = $input.first();
return [{ json: {
  estado: 'respondido_por_voz',
  canal: 'voz_telegram',
  chat_id: item.json.chat_id ?? null,
  caracteres_sintetizados: $('Blindaje 200 Caracteres').first().json.caracteres,
  binarios_purgados: true,
  timestamp: new Date().toISOString()
} }];  // se devuelve json nuevo, sin la propiedad binary

// El audio no utilizable tambien se descarta: un audio corrupto sigue siendo
// la voz de una persona y no debe quedar adherido a la ejecucion.
return [{ json: { estado: 'audio_descartado', motivo: 'transcripcion_vacia_o_ruido',
  binarios_purgados: true, timestamp: new Date().toISOString() } }];

// Telegram entrega las notas de voz como .oga. Groq valida la extension del
// archivo contra una lista cerrada que incluye ogg pero no oga, aunque el
// contenedor es el mismo. Se renombra el binario sin tocar los bytes.
const item = $input.first();

if (item.binary && item.binary.data) {
  item.binary.data.fileName = 'nota_de_voz.ogg';
  item.binary.data.fileExtension = 'ogg';
  item.binary.data.mimeType = 'audio/ogg';
}

return [item];

// El nodo de ElevenLabs rotula la salida como mp3 aunque el Output Format sea
// OPUS. Telegram decide como renderizar el archivo segun el mime declarado, no
// segun los bytes, asi que hay que corregir la etiqueta.
const item = $input.first();

if (item.binary && item.binary.data) {
  item.binary.data.fileName = 'respuesta.ogg';
  item.binary.data.fileExtension = 'ogg';
  item.binary.data.mimeType = 'audio/ogg';
}

return [item];
